import{z as B,x as d,o as l,c as p,q as o,j as E,D as r,d as t,s,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const k=JSON.parse('{"title":"基数与桶","description":"","frontmatter":{"title":"基数与桶","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/radix-bucket.md","filePath":"cs/radix-bucket.md","lastUpdated":1791413859000}'),A={name:"cs/radix-bucket.md"};function D(S,a,h,u,m,c){const n=d("Mermaid");return l(),p("div",null,[a[2]||(a[2]=o('<h1 id="基数与桶" tabindex="-1">基数与桶 <a class="header-anchor" href="#基数与桶" aria-label="Permalink to &quot;基数与桶&quot;">​</a></h1><div class="epigraph"><p>LSD 基数依赖稳定的按位分配；桶排序把均匀假设换成期望线性，最坏仍可退回比较。</p><footer>—— 据 Knuth, TAOCP vol. 3；CLRS 第 8 章整理</footer></div><p>上一课<a href="/cs/linear-time-sort">线性时间排序</a>已交出计数与 LSD 基数：键在 \\(\\{0,\\ldots,k\\}\\) 或 \\(d\\) 位数字上，\\(\\Theta(n+k)\\) 或 \\(\\Theta(d(n+r))\\)。主干停在「从低位到高位、子过程必须稳定」。本课不重写前缀和。缺口是两块对照：桶排序的概率模型，以及 MSD 与字符串——上一课点名未写。后课选择第 \\(k\\) 小仍回比较模型。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>计数要值域数组。若键是 \\([0,1)\\) 上的实数（或已归一化），不能直接当索引。桶排序：划 \\(n\\) 个等宽桶，落入同一桶的用插入排，再拼接。均匀独立时每桶期望 \\(O(1)\\) 个，总期望 \\(\\Theta(n)\\)；最坏一桶装完，\\(O(n^2)\\)。缺口不是再推翻比较下界，而是<strong>期望线性买分布假设</strong>，与计数的最坏线性分开。</p><p>MSD 基数：先按最高位分桶，再对每个非空桶递归。对变长字符串自然：已分叉的前缀不必再比。LSD 要定长或先按长度垫。稳定：LSD 必须；MSD 分桶后各桶独立，桶内可用插入或再 MSD。</p><h3 id="桶不是散列" tabindex="-1">桶不是散列 <a class="header-anchor" href="#桶不是散列" aria-label="Permalink to &quot;桶不是散列&quot;">​</a></h3><p>散列打散且不保序。桶的编号是键的单调函数，拼接才有序。把哈希表当排序是另一错误模型。计数是桶的极端：每个键值一个桶，桶内至多计数、没有比较。</p><p><span class="marginnote">桶排序像发牌前先按花色分四堆：分堆是「分配」不是「比较」，堆内牌少、随手插入即可，最后按花色顺序把堆连起来就整体有序。哈希表则是故意把牌打散，堆与堆之间连不起来。</span></p><p><span class="marginnote">Knuth 把分配排序与比较排序分卷叙述。CLRS 8.4 桶排序、8.3 基数。本课把上一课未写的均匀假设与 MSD 收进来，不把浮点位型再映射一遍。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>桶：算桶号 \\(\\lfloor n\\cdot key\\rfloor\\)（键已在 \\([0,1)\\)），桶内插入，按桶号扫出。LSD：对 \\(j=1..d\\) 稳定计数按第 \\(j\\) 位。MSD：按最高位分配，对大小超过阈值的桶递归，小桶改插入。</p><p><span class="marginnote">代入一个数：\\(n=1000\\) 个键、划 1000 个桶，键 \\(0.0037\\) 落进桶 3（\\(1000\\times 0.0037=3.7\\) 向下取整）。均匀假设下每桶期望恰好 1 个键，桶内插入排序几乎不干活，总代价约线性。</span></p>',13)),(l(),E(i,null,{default:r(()=>[s(n,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20INT%5B%22%E6%95%B4%E6%95%B0%20%2F%20%E5%AE%9A%E9%95%BF%E6%95%B0%E5%AD%97%22%5D%20--%3E%20LSD%5B%22LSD%EF%BC%9A%E7%A8%B3%E5%AE%9A%E6%8C%89%E4%BD%8D%22%5D%0A%20%20REAL%5B%22%E5%9D%87%E5%8C%80%20%5B0%2C1)%22%5D%20--%3E%20BUCK%5B%22%E6%A1%B6%20%2B%20%E6%A1%B6%E5%86%85%E6%8F%92%E5%85%A5%22%5D%0A%20%20STR%5B%22%E5%8F%98%E9%95%BF%E4%B8%B2%22%5D%20--%3E%20MSD%5B%22MSD%EF%BC%9A%E5%89%8D%E7%BC%80%E5%88%86%E5%8F%89%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"正确性：LSD 归纳「最低 \\(j\\) 位有序」；MSD 归纳「当前前缀已对齐，桶间有序」。桶的期望对输入分布，不是算法抛硬币。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,[t("空间：桶指针加计数数组。缓存：大量随机桶号会打散写，实践上不如比较排序友好——本课点名，不模拟 Cache。与"),e("a",{href:"/cs/quicksort-3way"},"三路快排"),t("：MSD 的「当前位相等」进入同一子桶，语义相近，模型仍是数字位而非比较。")],-1)),a[6]||(a[6]=e("p",null,[e("span",{class:"marginnote"},"容易把「期望 \\(\\Theta(n)\\)」听成「总是很快」。期望是给输入分布上保险：数据若挤在 \\([0, 0.1)\\) 这十分之一区间里，大多数键落进同一批桶，退化成桶内平方级，反而不如比较排序。")],-1)),(l(),E(i,null,{default:r(()=>[s(n,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20K%5B%22%E8%BE%93%E5%85%A5%E9%94%AE%3A%200%20%E5%88%B0%201%20%E4%B9%8B%E9%97%B4%E7%9A%84%E5%AE%9E%E6%95%B0%22%5D%20--%3E%20BN%5B%22%E6%A1%B6%E5%8F%B7%20%3D%20floor(n%20*%20key)%22%5D%0A%20%20BN%20--%3E%20B0%5B%22%E6%A1%B6%200%22%5D%0A%20%20BN%20--%3E%20B1%5B%22%E6%A1%B6%201%22%5D%0A%20%20BN%20--%3E%20B2%5B%22%E6%A1%B6%202%20%E2%80%A6%22%5D%0A%20%20B0%20--%3E%20IS%5B%22%E6%A1%B6%E5%86%85%E6%8F%92%E5%85%A5%E6%8E%92%E5%BA%8F%22%5D%0A%20%20B1%20--%3E%20IS%0A%20%20B2%20--%3E%20IS%0A%20%20IS%20--%3E%20OUT%5B%22%E6%8C%89%E6%A1%B6%E5%8F%B7%E6%8B%BC%E6%8E%A5%20%3D%20%E6%9C%89%E5%BA%8F%E8%BE%93%E5%87%BA%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=o('<p>\\(k\\) 或 \\(r\\) 随 \\(n\\) 增长时，线性系数变差。单词长 RAM 上的整数排序更快，仍不启用。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不声称一般排序 \\(O(n)\\)。没有值域或分布，比较墙仍在。外存多路归并不是桶。后课默认：LSD/MSD 与桶的假设已分开；第 \\(k\\) 小回到比较模型，不必排完。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>LSD 要稳定按位；MSD 适合变长前缀。</li><li>桶排序期望线性依赖均匀；最坏平方。</li><li>选择第 \\(k\\) 小不是全排序，下一课另开。</li><li>出处：Knuth, TAOCP vol. 3；CLRS 第 8 章。</li></ul>',5))])}const T=B(A,[["render",D]]);export{k as __pageData,T as default};
